{"command": "# List Slack users to find Alex Torres and platform team members
curl -s "$SLACK_URL/api/users.list" 2>&1 | python3 -c "
import json,sys
data=json.load(sys.stdin)
for u in data.get('members',[]):
    if not u.get('is_bot') and not u.get('deleted'):
        prof = u.get('profile',{})
        print(f\"{u['id']} | {u.get('name','')} | {prof.get('real_name','')} | {prof.get('email','')} | title={prof.get('title','')}\")
" 2>&1", "timeout": 10}

